+                    <span v-localize>{{ action.title }}</span>
+                </BButton>
+            </div>
+        </div>
+        <LoadingSpan v-if="loading" />
+        <BAlert v-else-if="!isAvailable" variant="info" show>
+            <span v-if="searchTerm" v-localize>
