+                                <FontAwesomeIcon v-if="sortDesc" icon="caret-up" data-description="grid sort asc" />
+                                <FontAwesomeIcon v-else icon="caret-down" data-description="grid sort desc" />
+                            </span>
+                        </BLink>
+                    </span>
+                    <span v-else>{{ fieldEntry.title || fieldEntry.key }}</span>
