+            <tr v-for="(rowData, rowIndex) in gridData" :key="rowIndex" :class="{ 'grid-dark-row': rowIndex % 2 }">
+                <td
+                    v-for="(fieldEntry, fieldIndex) in config.fields"
+                    :key="fieldIndex"
+                    class="px-2 py-3"
+                    :style="{ width: `${fieldEntry.width}%` }"
+                    :data-description="`grid cell ${rowIndex}-${fieldIndex}`">
